from pathlib import Path
Path('context-pruning-regression.test.ts').write_text('''import { afterAll, expect, test } from "bun:test";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ContextPruningTracker } from "./src/core/context-pruning/tracker.ts";
import { recoverablePrune } from "./src/core/context-pruning/recovery.ts";

const root = mkdtempSync(join(tmpdir(), "aide-pruning-regression-"));
afterAll(() => rmSync(root, { recursive: true, force: true }));
const output = "résultat 🔎\\n".repeat(500);
const args = { query: "example" };
const run = (tracker: ContextPruningTracker, call: string) =>
  tracker.process(call, "code_search", args, output,
    recoverablePrune(root, "session", call, output));

test("final emitted output and retained originals survive history reload with byte accounting", () => {
  const tracker = new ContextPruningTracker(root);
  const first = run(tracker, "first");
  const second = run(tracker, "second");
  const third = run(tracker, "third");
  expect(third.output).toContain("callId: first");
  expect(readFileSync(second.recoveryPath!, "utf8")).toBe(output);
  expect(tracker.getHistory().map(r => r.prunedOutput)).toEqual([null, second.output, third.output]);
  expect(tracker.getHistory().every(r => r.originalOutput === output)).toBe(true);
  const saved = Buffer.byteLength(output) * 2 - Buffer.byteLength(second.output) - Buffer.byteLength(third.output);
  expect(tracker.getStats()).toEqual({
    totalCalls: 3, prunedCalls: 2, totalBytesSaved: saved,
    estimatedContextBytes: [first, second, third].reduce((sum, r) => sum + Buffer.byteLength(r.output), 0),
  });
  const restored = new ContextPruningTracker(root);
  restored.loadHistory(JSON.parse(JSON.stringify(tracker.getHistory())));
  expect(restored.getStats()).toEqual(tracker.getStats());
  expect(run(restored, "fourth").output).toContain("callId: first");
});

test("evicted full result is replaced by a new full baseline, including after reload", () => {
  const tracker = new ContextPruningTracker(root, 2);
  run(tracker, "a"); run(tracker, "b"); run(tracker, "c");
  const restored = new ContextPruningTracker(root, 2);
  restored.loadHistory(tracker.getHistory());
  expect(run(restored, "d").modified).toBe(false);
  expect(run(restored, "e").output).toContain("callId: d");
});

test("recovery rejection records the emitted full result as the latest baseline", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "a");
  const rejected = tracker.process("b", "code_search", args, output,
    recoverablePrune(root, "", "b", output));
  expect(rejected).toEqual({ output, modified: false, bytesSaved: 0 });
  expect(tracker.getHistory()[1].prunedOutput).toBeNull();
  expect(tracker.getStats()).toEqual({totalCalls: 2, prunedCalls: 0, totalBytesSaved: 0,
    estimatedContextBytes: Buffer.byteLength(output) * 2});
  expect(run(tracker, "c").output).toContain("callId: b");
});

test("recovery keeps small outputs and failed retention unchanged", () => {
  const blocked = join(root, "blocked");
  writeFileSync(blocked, "not a directory");
  for (const [cwd, original] of [[root, "short"], [blocked, output]]) {
    const tracker = new ContextPruningTracker(root);
    tracker.process("a", "code_search", args, original);
    const result = tracker.process("b", "code_search", args, original,
      recoverablePrune(cwd, "session", "b", original));
    expect(result).toEqual({ output: original, modified: false, bytesSaved: 0 });
    expect(tracker.getHistory()[1].prunedOutput).toBeNull();
    const restored = new ContextPruningTracker(root);
    restored.loadHistory(tracker.getHistory());
    expect(restored.getStats()).toEqual(tracker.getStats());
  }
});

test("shortened output is never a target even when a new original equals it", () => {
  const tracker = new ContextPruningTracker(root);
  run(tracker, "a");
  const second = run(tracker, "b");
  const third = tracker.process("c", "code_search", args, second.output);
  expect(third.modified).toBe(false);
});

test("different arguments and outputs stay distinct; equivalent reordered arguments deduplicate", () => {
  const tracker = new ContextPruningTracker(root);
  tracker.process("a", "Grep", {pattern: "x", path: ".", output_mode: "content"}, output);
  expect(tracker.process("b", "Grep", {pattern: "x", path: ".", output_mode: "files"}, output).modified).toBe(false);
  expect(tracker.process("c", "Grep", {path: ".", output_mode: "content", pattern: "x"}, output).output).toContain("callId: a");
  expect(tracker.process("d", "Grep", {pattern: "x", path: ".", output_mode: "content"}, output + "changed").modified).toBe(false);
  expect(tracker.process("e", "Grep", {pattern: "x", path: ".", output_mode: "content"}, output).output).toContain("callId: a");
  tracker.process("f", "code_search", {tool: "same", query: "x"}, output);
  expect(tracker.process("g", "code_outline", {tool: "same", query: "x"}, output).modified).toBe(false);
});

